// Automatically sort countries A-Z by country name, and states alphabetically (keeping "All States (Nationwide)" first)
export const globalCountriesData: CountryData[] = [...unsortedCountriesData]
  .sort((a, b) => a.country.localeCompare(b.country))
  .map(c => ({
    ...c,
    states: [
      "All States (Nationwide)",
      ...c.states.filter(s => s !== "All States (Nationwide)").sort((x, y) => x.localeCompare(y))
    ]
  }));
